INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (1, 'M01.4', 'Exam Question Bank', 4)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate 3/8 + 5/12', '[{"id": "a", "text": "8/20", "correct": false}, {"id": "b", "text": "19/24", "correct": true}, {"id": "c", "text": "15/96", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate 3¾ ÷ 1½', '[{"id": "a", "text": "5⅝", "correct": false}, {"id": "b", "text": "2½", "correct": true}, {"id": "c", "text": "0·4", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate 12 ÷ 4 × 3 + 2', '[{"id": "a", "text": "3", "correct": false}, {"id": "b", "text": "11", "correct": true}, {"id": "c", "text": "15", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'An engine develops 85 hp from a possible 125 hp. What percentage of the available power is being developed?', '[{"id": "a", "text": "40 %", "correct": false}, {"id": "b", "text": "68 %", "correct": true}, {"id": "c", "text": "147 %", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), '4180 rpm is 38 % of an engine''s maximum speed. What is the maximum speed?', '[{"id": "a", "text": "1588 rpm", "correct": false}, {"id": "b", "text": "4218 rpm", "correct": false}, {"id": "c", "text": "11 000 rpm", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A drive gear of 15 teeth meshes with a driven gear of 45 teeth. What is the ratio of revolutions, drive gear to driven gear?', '[{"id": "a", "text": "1 : 3", "correct": false}, {"id": "b", "text": "3 : 1", "correct": true}, {"id": "c", "text": "1 : 1", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), '£240 is to be divided between four men in the ratio 9 : 11 : 13 : 15. How much does the man on the largest share receive?', '[{"id": "a", "text": "£60", "correct": false}, {"id": "b", "text": "£75", "correct": true}, {"id": "c", "text": "£80", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'An aircraft covers 750 km in 3 hours 45 minutes. What is its average speed?', '[{"id": "a", "text": "166·7 km/h", "correct": false}, {"id": "b", "text": "200 km/h", "correct": true}, {"id": "c", "text": "250 km/h", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Solve 3(2y + 3) = 21', '[{"id": "a", "text": "y = 2", "correct": true}, {"id": "b", "text": "y = 3", "correct": false}, {"id": "c", "text": "y = 9", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The volume of a cone is V = πr²h/3. Transposed to make r the subject, this becomes:', '[{"id": "a", "text": "r = 3V/πh", "correct": false}, {"id": "b", "text": "r = √(3V/πh)", "correct": true}, {"id": "c", "text": "r = √(V/3πh)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Solve the simultaneous equations 2x + 3y = 8 and 3x + 5y = 11. The value of x is:', '[{"id": "a", "text": "x = 1", "correct": false}, {"id": "b", "text": "x = 7", "correct": true}, {"id": "c", "text": "x = −7", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The roots of 6x² − 5x − 6 = 0 are:', '[{"id": "a", "text": "x = 1½ and x = −⅔", "correct": true}, {"id": "b", "text": "x = −1½ and x = ⅔", "correct": false}, {"id": "c", "text": "there are no real roots", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Expanded, (a + b)² is equal to:', '[{"id": "a", "text": "a² + b²", "correct": false}, {"id": "b", "text": "a² + 2ab + b²", "correct": true}, {"id": "c", "text": "a² + ab + b²", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Simplify 3a²b / 6ab²', '[{"id": "a", "text": "a / 2b", "correct": true}, {"id": "b", "text": "2a / b", "correct": false}, {"id": "c", "text": "a² / 2b²", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A car costs seven times as much as a motorcycle. Two cars and three motorcycles together cost £8500. What does one motorcycle cost?', '[{"id": "a", "text": "£500", "correct": true}, {"id": "b", "text": "£850", "correct": false}, {"id": "c", "text": "£1214", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Solve (x − 4)/3 − (2x − 1)/2 = 4', '[{"id": "a", "text": "x = −7·25", "correct": true}, {"id": "b", "text": "x = 7·25", "correct": false}, {"id": "c", "text": "x = −8·75", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The value of 2⁻³ is:', '[{"id": "a", "text": "−8", "correct": false}, {"id": "b", "text": "−6", "correct": false}, {"id": "c", "text": "1/8", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Simplify a⁵ × a³ ÷ a²', '[{"id": "a", "text": "a¹⁰", "correct": false}, {"id": "b", "text": "a⁶", "correct": true}, {"id": "c", "text": "a⁷·⁵", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Written in standard form, 0·002 is:', '[{"id": "a", "text": "2·0 × 10⁻³", "correct": true}, {"id": "b", "text": "0·2 × 10⁻²", "correct": false}, {"id": "c", "text": "2·0 × 10³", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The binary number 101101₂ expressed in decimal is:', '[{"id": "a", "text": "43", "correct": false}, {"id": "b", "text": "45", "correct": true}, {"id": "c", "text": "53", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The decimal number 29 expressed in binary is:', '[{"id": "a", "text": "10111", "correct": false}, {"id": "b", "text": "11101", "correct": true}, {"id": "c", "text": "11011", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The octal number 376₈ expressed in decimal is:', '[{"id": "a", "text": "254", "correct": true}, {"id": "b", "text": "376", "correct": false}, {"id": "c", "text": "886", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The hexadecimal number A7₁₆ expressed in binary is:', '[{"id": "a", "text": "10100111", "correct": true}, {"id": "b", "text": "10100110", "correct": false}, {"id": "c", "text": "11100101", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Given that log₁₀ 2 = 0·301, the value of log₁₀ 200 is:', '[{"id": "a", "text": "0·602", "correct": false}, {"id": "b", "text": "2·301", "correct": true}, {"id": "c", "text": "3·010", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The sum of the interior angles of a hexagon is:', '[{"id": "a", "text": "360°", "correct": false}, {"id": "b", "text": "720°", "correct": true}, {"id": "c", "text": "1080°", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A right-angled triangle has sides of 5 mm and 12 mm about the right angle. The hypotenuse is:', '[{"id": "a", "text": "8·5 mm", "correct": false}, {"id": "b", "text": "13 mm", "correct": true}, {"id": "c", "text": "17 mm", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A wheel of diameter 715 mm makes 30 complete revolutions. The distance travelled is:', '[{"id": "a", "text": "21·45 m", "correct": false}, {"id": "b", "text": "67·4 m", "correct": true}, {"id": "c", "text": "134·8 m", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'One radian is equal to approximately:', '[{"id": "a", "text": "3·142°", "correct": false}, {"id": "b", "text": "6·2832°", "correct": false}, {"id": "c", "text": "57·3°", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A two-cylinder engine has a bore of 77 mm and a stroke of 89 mm. Its total cubic capacity is:', '[{"id": "a", "text": "414·44 cm³", "correct": false}, {"id": "b", "text": "828·88 cm³", "correct": true}, {"id": "c", "text": "3315·5 cm³", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A trapezium has parallel sides of 8 cm and 12 cm, and a vertical height of 5 cm. Its area is:', '[{"id": "a", "text": "40 cm²", "correct": false}, {"id": "b", "text": "50 cm²", "correct": true}, {"id": "c", "text": "100 cm²", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A volume of 2 500 000 mm³ expressed in cm³ is:', '[{"id": "a", "text": "2500 cm³", "correct": true}, {"id": "b", "text": "25 000 cm³", "correct": false}, {"id": "c", "text": "250 000 cm³", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The area of a circle of diameter 20 mm is: — 30 — Module 1 — exam practice Part-66 (common)', '[{"id": "a", "text": "62·8 mm²", "correct": false}, {"id": "b", "text": "314·2 mm²", "correct": true}, {"id": "c", "text": "1256·6 mm²", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'In the equation of a straight line, y = mx + c, the term c represents:', '[{"id": "a", "text": "the gradient of the line", "correct": false}, {"id": "b", "text": "the intercept on the y-axis", "correct": true}, {"id": "c", "text": "the intercept on the x-axis", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'When data is plotted, the quantity placed on the horizontal (x) axis is:', '[{"id": "a", "text": "the dependent variable", "correct": false}, {"id": "b", "text": "the independent variable", "correct": true}, {"id": "c", "text": "always time", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A graph of the function y = kx² produces:', '[{"id": "a", "text": "a straight line through the origin", "correct": false}, {"id": "b", "text": "a parabola", "correct": true}, {"id": "c", "text": "a sine wave", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'On a graph of speed against time, the area beneath the curve represents:', '[{"id": "a", "text": "the acceleration", "correct": false}, {"id": "b", "text": "the distance travelled", "correct": true}, {"id": "c", "text": "the average speed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The period of the function y = sin x is:', '[{"id": "a", "text": "90°", "correct": false}, {"id": "b", "text": "180°", "correct": false}, {"id": "c", "text": "360°", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A church spire is 60 m high. From a theodolite on level ground the angle between the line of sight to the top and the horizontal is 15°. The distance from the theodolite to the base of the spire is:', '[{"id": "a", "text": "16·1 m", "correct": false}, {"id": "b", "text": "223·9 m", "correct": true}, {"id": "c", "text": "231·8 m", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'In a right-angled triangle the sides are 3, 4 and 5 units. Taking φ as the angle opposite the side of 3 units, cos φ is:', '[{"id": "a", "text": "0·6", "correct": false}, {"id": "b", "text": "0·75", "correct": false}, {"id": "c", "text": "0·8", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'If sin θ = 0·5, the angle θ is:', '[{"id": "a", "text": "30°", "correct": true}, {"id": "b", "text": "45°", "correct": false}, {"id": "c", "text": "60°", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'For an angle lying in the second quadrant (between 90° and 180°), which of the following is positive?', '[{"id": "a", "text": "sine only", "correct": true}, {"id": "b", "text": "cosine only", "correct": false}, {"id": "c", "text": "tangent only", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The three sides of a triangle are known, but none of its angles. To find an angle you would use:', '[{"id": "a", "text": "the sine rule", "correct": false}, {"id": "b", "text": "the cosine rule", "correct": true}, {"id": "c", "text": "Pythagoras'' theorem", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The value of tan 90° is:', '[{"id": "a", "text": "0", "correct": false}, {"id": "b", "text": "1", "correct": false}, {"id": "c", "text": "infinity", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The mid-point of the straight line joining the points (2, 1) and (6, 4) is:', '[{"id": "a", "text": "(4, 2·5)", "correct": true}, {"id": "b", "text": "(4, 3)", "correct": false}, {"id": "c", "text": "(8, 5)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The rectangular co-ordinates (2, 1) expressed in polar form are:', '[{"id": "a", "text": "(2·236, 26·57°)", "correct": true}, {"id": "b", "text": "(2·236, 63·43°)", "correct": false}, {"id": "c", "text": "(3, 26·57°)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'To convert the polar co-ordinates (r, φ) to rectangular co-ordinates, the x value is given by:', '[{"id": "a", "text": "x = r sin φ", "correct": false}, {"id": "b", "text": "x = r cos φ", "correct": true}, {"id": "c", "text": "x = r / cos φ", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The fraction 7/8 expressed as a decimal is:', '[{"id": "a", "text": "0·785", "correct": false}, {"id": "b", "text": "0·875", "correct": true}, {"id": "c", "text": "0·878", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate 3/8 + 1/6', '[{"id": "a", "text": "4/14", "correct": false}, {"id": "b", "text": "13/24", "correct": true}, {"id": "c", "text": "3/48", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate −6 − (−4)', '[{"id": "a", "text": "−10", "correct": false}, {"id": "b", "text": "−2", "correct": true}, {"id": "c", "text": "+2", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), '15 % of 640 is:', '[{"id": "a", "text": "9·6", "correct": false}, {"id": "b", "text": "42·7", "correct": false}, {"id": "c", "text": "96", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), '0·375 expressed as a fraction in its lowest terms is:', '[{"id": "a", "text": "3/8", "correct": true}, {"id": "b", "text": "3/4", "correct": false}, {"id": "c", "text": "375/1000", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The highest common factor of 24 and 60 is:', '[{"id": "a", "text": "6", "correct": false}, {"id": "b", "text": "12", "correct": true}, {"id": "c", "text": "120", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The lowest common multiple of 4, 6 and 8 is:', '[{"id": "a", "text": "12", "correct": false}, {"id": "b", "text": "24", "correct": true}, {"id": "c", "text": "48", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Evaluate 2·5 × 0·04', '[{"id": "a", "text": "0·01", "correct": false}, {"id": "b", "text": "0·1", "correct": true}, {"id": "c", "text": "1·0", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'A tank holds 200 imperial gallons. Using a conversion factor of 4·546, its capacity in litres is:', '[{"id": "a", "text": "44 litres", "correct": false}, {"id": "b", "text": "90·92 litres", "correct": false}, {"id": "c", "text": "909·2 litres", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The average of 12, 15, 9 and 16 is:', '[{"id": "a", "text": "13", "correct": true}, {"id": "b", "text": "14", "correct": false}, {"id": "c", "text": "52", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The value of √0·25 is:', '[{"id": "a", "text": "0·05", "correct": false}, {"id": "b", "text": "0·5", "correct": true}, {"id": "c", "text": "0·125", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The value of 3³ is:', '[{"id": "a", "text": "9", "correct": false}, {"id": "b", "text": "27", "correct": true}, {"id": "c", "text": "6", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Simplify 5x − 2(x − 3)', '[{"id": "a", "text": "3x − 6", "correct": false}, {"id": "b", "text": "3x + 6", "correct": true}, {"id": "c", "text": "7x − 6", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Solve 4x − 7 = 2x + 5', '[{"id": "a", "text": "x = 1", "correct": false}, {"id": "b", "text": "x = 6", "correct": true}, {"id": "c", "text": "x = −6", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The formula I = V/R transposed to make R the subject is:', '[{"id": "a", "text": "R = V/I", "correct": true}, {"id": "b", "text": "R = VI", "correct": false}, {"id": "c", "text": "R = I/V", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Solve x/3 = 12', '[{"id": "a", "text": "x = 4", "correct": false}, {"id": "b", "text": "x = 15", "correct": false}, {"id": "c", "text": "x = 36", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Factorised completely, 4a² − 8ab becomes:', '[{"id": "a", "text": "4a(a − 2b)", "correct": true}, {"id": "b", "text": "4ab(a − 2)", "correct": false}, {"id": "c", "text": "4a(a − 8b)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The roots of x² − 5x + 6 = 0 are:', '[{"id": "a", "text": "x = 2 and x = 3", "correct": true}, {"id": "b", "text": "x = −2 and x = −3", "correct": false}, {"id": "c", "text": "x = 1 and x = 6", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'Simplify 10⁴ × 10⁻²', '[{"id": "a", "text": "10⁻⁸", "correct": false}, {"id": "b", "text": "10²", "correct": true}, {"id": "c", "text": "10⁶", "correct": false}]'::jsonb, '{B1,B2}'),
