    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The decimal number 12 expressed in binary is:', '[{"id": "a", "text": "1010", "correct": false}, {"id": "b", "text": "1100", "correct": true}, {"id": "c", "text": "1110", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The hexadecimal digit F has a decimal value of:', '[{"id": "a", "text": "15", "correct": true}, {"id": "b", "text": "16", "correct": false}, {"id": "c", "text": "20", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M01.4'), 'The value of log₁₀ 1000 is:', '[{"id": "a", "text": "3", "correct": true}, {"id": "b", "text": "30", "correct": false}, {"id": "c", "text": "100", "correct": false}]'::jsonb, '{B1,B2}'),
